param()

$ErrorActionPreference = 'Stop'
$projectRoot = Split-Path -Parent $PSScriptRoot
$publicRoot = Join-Path $projectRoot 'public'

function Write-SpanishPage {
  param(
    [Parameter(Mandatory)] [string] $Source,
    [Parameter(Mandatory)] [string] $Destination,
    [Parameter(Mandatory)] [System.Collections.Specialized.OrderedDictionary] $Replacements
  )

  $html = [System.IO.File]::ReadAllText($Source)
  foreach ($entry in $Replacements.GetEnumerator()) {
    if (-not $html.Contains([string] $entry.Key)) {
      throw "Spanish build source text was not found in $Source`: $($entry.Key)"
    }
    $html = $html.Replace([string] $entry.Key, [string] $entry.Value)
  }

  $destinationDirectory = Split-Path -Parent $Destination
  [System.IO.Directory]::CreateDirectory($destinationDirectory) | Out-Null
  [System.IO.File]::WriteAllText($Destination, $html, [System.Text.UTF8Encoding]::new($false))
}

