function New-LandingReplacements {
  param([string] $EnglishUrl, [string] $SpanishUrl, [string] $SpanishToggleHref)
  $map = [ordered]@{}
  foreach ($entry in $shared.GetEnumerator()) { $map.Add($entry.Key, $entry.Value) }
  $map.Add(('<link rel="canonical" href="{0}" />' -f $EnglishUrl), ('<link rel="canonical" href="{0}" />' -f $SpanishUrl))
  $map.Add(('<meta property="og:url" content="{0}" />' -f $EnglishUrl), ('<meta property="og:url" content="{0}" />' -f $SpanishUrl))
  $englishPath = ([uri] $EnglishUrl).AbsolutePath
  $map.Add(('href="{0}" hreflang="es" lang="es" data-language-switch="en"' -f $SpanishToggleHref), ('href="{0}" hreflang="en" lang="en" data-language-switch="en"' -f $englishPath))
  $map.Add(('"@id": "{0}#webpage"' -f $EnglishUrl), ('"@id": "{0}#webpage"' -f $SpanishUrl))
  $map.Add(('"url": "{0}"' -f $EnglishUrl), ('"url": "{0}"' -f $SpanishUrl))
  $map.Add(('"item": "{0}"' -f $EnglishUrl), ('"item": "{0}"' -f $SpanishUrl))
  return $map
}

